use vstd::prelude::*;

verus! {
    // Compute the length of the longest contiguous strictly increasing streak
    // in the input vector nums.  If nums is empty, return 0.
    // The result is always ≤ nums.len().
    fn longest_increasing_streak(nums: &Vec<i32>) -> usize
        ensures
            result <= nums.len(),
    {
        let n = nums.len();
        // Handle the empty‐array case up front.
        if n == 0 {
            return 0;
        }

        // We know n ≥ 1 here.
        // curr_streak = length of increasing streak ending at index i−1
        // max_streak  = maximum streak length seen so far (also ≥1)
        let mut curr_streak: usize = 1;
        let mut max_streak: usize = 1;
        let mut i: usize = 1;

        // We will scan from i=1 up to i=n−1, updating streak lengths.
        while i < n
            invariant
                // i remains in bounds
                i <= n,
                // curr_streak is at least 1 and at most i
                1 <= curr_streak <= i,
                // max_streak is at least 1 and at most i
                1 <= max_streak <= i,
            decreases n - i,
        {
            // If the current element continues a strictly increasing run,
            // bump up curr_streak, otherwise reset to 1.
            if nums[i] > nums[i - 1] {
                curr_streak += 1;
            } else {
                curr_streak = 1;
            }

            // Update the global maximum if needed.
            if curr_streak > max_streak {
                max_streak = curr_streak;
            }

            // Move on to the next index.
            i += 1;
        }

        // At loop exit, i == n, so by invariant max_streak ≤ i = n.
        max_streak
    }
}

fn main() {
    // Example usages (not verified by Verus, but for runtime sanity):

    let v1: Vec<i32> = vec![];
    assert!(longest_increasing_streak(&v1) == 0);

    let v2 = vec![1, 2, 2, 3, 4, 1, 2, 3];
    // The longest strictly increasing runs are [1,2], [2,3,4], and [1,2,3].
    // Their lengths are 2, 3, and 3, so the answer is 3.
    assert!(longest_increasing_streak(&v2) == 3);
}